/bin/bash -lc "python - <<'PY'
import copy, json
import api, core, model, service, render

assert model.Result is service.Result if hasattr(service, 'Result') else True
r = service.compute([{'a':[1,2]}, [['add','/a/1',9], ['test','/a/1',9]]])
assert isinstance(r, model.Result) and r.value == {'ok':True,'document':{'a':[1,9,2]}}
assert json.loads(render.present(r)) == r.value

original = {'a':[1,2]}
assert core.solve([original, [['add','/a/-',3], ['replace','/x',0]]]) == {'ok':False,'document':original}
assert original == {'a':[1,2]}
assert core.solve([1, [['remove','']]]) == {'ok':True,'document':None}
assert core.solve([[0], [['add','/01',1]]]) == {'ok':False,'document':[0]}

payload = [
 {'op':'put','key':'k','input':[{'v':[1]}, [['add','/v/-',2]]]},
 {'op':'begin','id':'b'},
 {'op':'delete','key':'k'},
 {'op':'rollback','id':'r'},
 {'op':'rollback','id':'r'},
 {'op':'list'},
 {'op':'get','key':'k'},
 {'op':'expect','key':'k','value':{'ok':True,'document':{'v':[1,2]}}},
 {'op':'begin','id':'same'},
 {'op':'begin','id':'same','extra':1},
 {'op':'bad','id':'unused'},
 {'op':'get','id':'unused'},
]
out = json.loads(api.run(json.dumps(payload)))
assert len(out['events']) == len(payload)
assert out['events'][1] == {'ok':1} and out['events'][3] == {'ok':0} and out['events'][4] == {'ok':0}
assert out['events'][5]['ok'][0][0] == 'k'
assert out['events'][7] == {'ok':True}
assert out['events'][9] == {'error':'id-conflict'}
assert out['events'][11] == {'error':'command'}
assert out['events'][12] == {'error':'command'}
assert json.loads(api.run('[]')) == {'events': [], 'state': [], 'depth': 0}
print('validation passed')
PY"

